KEYWORDS = {"let", "fn", "if", "else", "while", "return", "print", "true", "false"}
OPERATORS = ["==", "!=", "<=", ">=", "&&", "||", "->",
             "+", "-", "*", "/", "%", "^", "=", "<", ">", "!",
             "(", ")", "{", "}", ",", ";", ":"]
