LITERALS = ("num", "str", "bool")

APPLY = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": lambda a, b: a / b,
    "%": lambda a, b: a % b,
    "^": lambda a, b: a ** b,
    "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b,
    ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
    "==": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
}
COMPARISONS = ("<", "<=", ">", ">=", "==", "!=")


def format_value(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def eval_expr(node, env):
    kind = node[0]
    if kind in LITERALS:
        return node[1]
    if kind == "var":
        return env[node[1]]
    if kind == "unary":
        value = eval_expr(node[2], env)
        return (not value) if node[1] == "!" else -value
    if kind == "bin":
        op = node[1]
        if op == "&&":
            return eval_expr(node[2], env) and eval_expr(node[3], env)
        if op == "||":
