        elif kind == "expr":
            eval_expr(node[1], env)
        elif kind == "if":
            run_block(node[2] if eval_expr(node[1], env) else node[3], env, out)
        elif kind == "while":
            spins = 0
            while eval_expr(node[1], env):
                spins += 1
                if spins > 100000:
                    raise RuntimeError("runaway loop")
                run_block(node[2], env, out)
