s = s + "c";
print s;
print true;
print 1 == 2;
')
assert _got == ["abc", "true", "false"], f"got {_got!r}, expected ['abc', 'true', 'false']"
_got = run_source('print "tab:\there";')
assert _got == ["tab:	here"], f"escapes should be decoded by the lexer, got {_got!r}"

from codegen import run_source
